INSERT INTO products (name, description, price, category_id, stock) VALUES
    ('Sony WH-1000XM5', E'Флагманские наушники с активным шумоподавлением.\n\nДва процессора HD Noise Canceling, 30 часов автономной работы, быстрая зарядка 3 мин = 3 часа. Мягкие амбушюры, складывающаяся конструкция.\n\nПоддержка LDAC, multipoint-подключение к двум устройствам одновременно.', 349.99, 3, 40),
    ('Logitech C920', E'Full HD веб-кamera 1080p/30fps для стримов и видеозвонков.\n\nАвтофокус, стереомикрофоны с шумоподавлением, совместимость с Zoom, Teams, OBS. Крепление на монитор или штатив.\n\nPlug-and-play через USB-A, не требует драйверов на macOS и Windows.', 79.99, 1, 60),
    ('Dell UltraSharp 27"', E'27-дюймовый IPS-монитор с разрешением QHD 2560×1440.\n\n99% sRGB, USB-C с Power Delivery 65W, встроенный USB-hub. Регулировка по высоте, наклону и pivot 90°.\n\nТонкие рамки — удобно для multi-monitor setup. Подходит для дизайна, кода и офисной работы.', 449.99, 1, 25),
    ('Anker USB-C Hub 7-in-1', E'Компактный USB-C хаб для ноутбуков.\n\nHDMI 4K@30Hz, 2× USB-A 3.0, SD/microSD, USB-C PD 100W pass-through. Алюминиевый корпус, размером с кредитку.\n\nСовместим с MacBook, ThinkPad, Dell XPS и другими USB-C устройствами.', 49.99, 5, 80),
    ('Samsung SSD 990 PRO 1TB', E'NVMe SSD PCIe 4.0 с чтением до 7450 MB/s.\n\nФорм-фактор M.2 2280, DRAM-кэш, ресурс 600 TBW. Подходит для игр, монтажа видео и быстрой загрузки ОС.\n\nВ комплекте: SSD, документация. Совместим с PS5 (слот расширения).', 129.99, 1, 45),
    ('Clean Code', E'Культовая книга Robert C. Martin о написании чистого кода.\n\nПринципы именования, функций, классов, тестирования. Примеры на Java, но применимо к любому языку. Обязательна для каждого профессионального разработчика.\n\nМягкий переплёт, 464 страницы, издание на английском.', 44.99, 2, 35),
    ('Designing Data-Intensive Applications', E'Фундаментальный труд Martin Kleppmann о системах данных.\n\nБазы данных, репликация, партиционирование, batch и stream processing. Глубокое понимание trade-offs при проектировании архитектуры.\n\nРекомендуется senior-разработчикам и архитекторам. 616 страниц.', 54.99, 2, 28),
    ('Xiaomi LED Desk Lamp', E'Настольная LED-лампа с регулировкой яркости и цветовой температуры.\n\n4 режима освещения: чтение, работа за компьютером, вечерний отдых. Без мерцания, CRI > 90.\n\nМинималистичный дизайн, питание через USB-C, поворотная головка на 180°.', 39.99, 4, 55),
    ('Rain Design mStand', E'Алюминиевый подставка для ноутбука с эргономичным углом 18°.\n\nПоднимает экран на 15 см, улучшает осанку, освобождает место на столе. Отверстие для кабелей, резиновые ножки против скольжения.\n\nПодходит для MacBook и ноутбуков 11–17 дюймов.', 59.99, 4, 30),
    ('Ceramic Coffee Mug', E'Керамическая кружка 350 мл с двойными стенками.\n\nСохраняет температуру напитка до 2 часов, не обжигает руки. Матовое покрытие, подходит для посудомойки.\n\nИдеальна для домашнего офиса и подарка коллеге.', 14.99, 4, 120),
    ('SteelSeries QcK XXL', E'Игровой коврик для мыши размером 900×400 мм.\n\nМикротканевая поверхность, резиновое основание, прошитые края. Подходит для low и high DPI сенсоров.\n\nПокрывает клавиатуру и мышь, создавая единую рабочую зону.', 24.99, 5, 90),
    ('Apple AirPods Pro 2', E'Беспроводные наушники с чипом H2 и ANC нового поколения.\n\nAdaptive Audio, Transparency mode, пространственный звук. До 6 часов с ANC, кейс MagSafe.\n\nIP54, совместимы с iPhone, iPad, Mac и Android через Bluetooth 5.3.', 249.99, 3, 50);
